<?php require 'bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();q('UPDATE privacy_requests SET status="completed" WHERE id=?',[(int)post('id')]);flash('บันทึกว่าดำเนินคำขอแล้ว');go('admin/privacy_requests.php');}admin_header('คำขอข้อมูลส่วนบุคคล');?><p>ผู้ดูแลต้องตรวจสอบตัวตน ดำเนินการตามคำขอจริงและแจ้งเจ้าของบัญชีก่อนปิดงาน ปุ่มนี้บันทึกสถานะเท่านั้น ไม่ได้ลบหรือส่งออกข้อมูลอัตโนมัติ</p><?php foreach(q('SELECT r.*,u.name,u.email FROM privacy_requests r JOIN users u ON r.user_id=u.id ORDER BY r.id DESC') as $r):?><article class="panel"><h2><?=e($r['name'])?> · <?=e($r['type'])?></h2><p><?=e($r['email'])?> · <?=e($r['created_at'])?></p><p><?=e($r['details'])?></p><p><?=e($r['status'])?></p><?php if($r['status']==='pending'):?><form method="post" data-confirm="ดำเนินคำขอและแจ้งเจ้าของบัญชีแล้ว?"><?=csrf()?><input type="hidden" name="id" value="<?=$r['id']?>"><button>ดำเนินการแล้ว</button></form><?php endif ?></article><?php endforeach;admin_footer();?>
